package com.novacommerce.order.application; import com.novacommerce.order.api.error.OrderException; import com.novacommerce.order.domain.cart.*; import com.novacommerce.order.infrastructure.persistence.CartRepository; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CartService{private final CartRepository carts;private final Clock clock;public CartService(CartRepository c,Clock k){carts=c;clock=k;}@Transactional public Cart get(UUID owner){return carts.findOpen(owner).orElseGet(()->carts.save(new Cart(owner,clock.instant())));}@Transactional public Cart add(UUID owner,UUID variant,long q){Cart c=get(owner);ensureActive(c);c.add(variant,q,clock.instant());return c;}@Transactional public Cart update(UUID owner,UUID variant,long q){Cart c=get(owner);ensureActive(c);c.update(variant,q,clock.instant());return c;}@Transactional public void remove(UUID owner,UUID variant){Cart c=get(owner);ensureActive(c);c.remove(variant,clock.instant());}@Transactional public void clear(UUID owner){Cart c=get(owner);ensureActive(c);c.clear(clock.instant());}private void ensureActive(Cart c){if(c.getStatus()!=CartStatus.ACTIVE)throw new OrderException(HttpStatus.CONFLICT,"CART_CHECKOUT_IN_PROGRESS","Cart checkout is in progress");}}
